import{_ as a,c as e,o as t,ah as i}from"./chunks/framework.Dnh4IO1K.js";const h=JSON.parse('{"title":"周易經傳集解卷三十","description":"周易經傳集解 - 周易經傳集解卷三十","frontmatter":{"title":"周易經傳集解卷三十","description":"周易經傳集解 - 周易經傳集解卷三十"},"headers":[],"relativePath":"classics/jingchuan-jijie/031.md","filePath":"classics/jingchuan-jijie/031.md"}'),s={name:"classics/jingchuan-jijie/031.md"};function n(c,p,r,_,o,l){return t(),e("div",null,[...p[0]||(p[0]=[i('<p>欽定四庫全書</p><h1 id="周易經傳集解卷三十" tabindex="-1">周易經傳集解卷三十 <a class="header-anchor" href="#周易經傳集解卷三十" aria-label="Permalink to “周易經傳集解卷三十”">​</a></h1><p>宋林栗撰</p><p>序卦曰：「兌」者，說也。說而後取之，故受之以渙。「渙」者，離也。「渙」，「兌」之變也。自「兌」之「渙」，下變為「坎」，上反為「巽」，二、五不動而成也。下變為「坎」，則九二剛中，流而不盈，象所謂「剛來而不窮」也。上反為「巽」，則六四得位以承九五，彖所謂「柔得位而上同」也。夫所以為「兌」者，剛中而柔外也。以九居初，則剛而易窮；以六居上，則柔而失位也。是故「兌」之象為澤，澤以水聚為說者也。水聚而不流，則壅閼而為臭腐，枯滲而為涸竭矣。涸者，以其窮也；腐者，以其失位也。決而為「坎」，則剛來而不窮；反而為「巽」，則柔同而得位，所以為「渙」也。「渙」，散也，離也。人情喜說，則血氣流通，離散於四體而無所凝滯，是以謂之「渙」也。天下之勢，譬如一身，既已心說而誠服矣，雖散之四方萬里之遠，如居幾甸之中，可殺可辱，可飢可飽，而不可與叛其君，是則說而後散之之義也。「坎」為水，「巽」為風。風行水上，水凍消釋，舟楫通行，「渙」之象也。「渙」之「坎」、「兌」，不其然乎？</p><p>「渙」：亨，王假有廟，利涉大川，利貞。彖曰：「渙，亨」，剛來而不窮，柔得位乎外而上同。「王假有廟」，王乃在中也。「利涉大川」，乘木有功也。</p><p>下坎上巽，成卦曰「渙」者，初為坎，二為震，三為艮，四為巽。坎，北方也；震，東方也。艮，東北也；巽，東南也。一陽生於「坎」，而六陽盛於「巽」，陽氣周流乎其中，卦之所以為「渙」也。渙者，散也。人之血氣渙散，則其身安；國之政令流通，則其國治。故曰：「渙，亨。」而子曰：「渙，亨，剛來而不窮，柔得位乎外而上同。」釋所以亨之義也。夫所以為「坎」者，九二也。所以為「巽」者，六四也。以九居二，則剛來而不窮。以六居四，則柔得位乎外，而上同於九五也。剛來而不窮，德之所以流行也。柔得位乎外，令之所以布宣也。上同於五，君臣合志而上下同心也。如是而「亨」，不亦宜乎。「王假有廟，利涉大川，利貞。」何謂也？曰：假，大也。「王假有廟」者，非諸侯之所得有也。九五者，王之所居，而廟之所在乎？或曰：「萃、渙二卦，言王假有廟。萃，聚也；渙，散也。聚散不同，而有廟之義同，何也？」曰：天下萃聚而有君，然後王廟可以建；天下渙散而無事，然後王廟可以居。是故萃之廟在四，而渙之廟在五，各應其時義也。說者皆襲焦延壽之論，以上爻為宗廟。愚謂不然。宗廟者，國之本也，其在都邑之中矣。渙自五而下，有廟之象焉。故彖言王廟，而九五言「王居，明其所在也。延壽之論疏矣。」或曰：「廟在王居，則萃之在四，何也？」曰：「萃之時，王者方受天下之萃，可以致其孝享，而都邑未定，宗廟未立，故雖以九居五，有位而未光。然則廟之在四，宜矣。及渙之時，天下渙然各得其所，王者於是建都立邑，辨方正位，創其宗廟，作其宮室，以為子孫萬世之圖，是以系之九五也。昔周武王至於孟津，八百諸侯不期而會，斯之謂萃矣。王來自商，至於豐，歸馬於卒山之陽，放牛於桃林之野，列爵惟五，分土惟三，斯之謂渙矣。是故合而為一統，離而為萬邦，聚而為軍師卒伍，散而為士農工商，萃渙之別也。說者乃以散離之辭，為土崩瓦解之義，不亦以文害辭，以辭害意之甚者乎？」或曰：「然則有天下者，玉食萬方，萃有其象，而至於廟，則五而已。王假有廟，於何而取之？」曰：「夫子不云乎，王假有廟，王乃在中也。言自五以下，有七廟之象，而九二者，王在宗廟之中，致孝於神明之象也，不其然乎？」或曰：「九五，王也，二亦為王，何哉？」曰：「由天下歸往而言之，則五為王；由宗廟祭祀而言之，則二為王。五為王者，宅中之象也；二為王者，致孝之象也。」夫豈一端而足哉？是故五為「震」，二亦為「震」。「震」，長子而帝之出也。居五以臨天下，居二以事其先，斯為得之矣。其言「利涉大川」，則取諸坎巽也。坎為水，巽為風，以風乘木而行於水上，其「利涉」之象與？系曰：刳木為舟，剡木為楫，舟楫之利，以濟不通，蓋取諸渙，以其義也，「利貞」，何也？貞者，正也。天下渙然，必有持正者。莫為之正者，離散而無所統一，非「渙」之義矣。是故九五正位居中，而天下各得其所，斯「利貞」之謂與！或曰：子以陰陽往復，取諸夏時，則既有徵。今又曰：「一陽生於坎，而六陽盛於巽，何謂也？」曰：是何言與？六經之道，天人之理，無所不該，而況易之為書，又其至者。窮壤之間，苟有是理，聖人烏得而遺之？顧乾、坤、復、姤之配，取諸離、坎，不應象類，愚是以辨之。若蠱之「先甲」「後甲」，蓋取諸坎；而巽之「先庚」「後庚」，亦取諸離。聖人於蠱、剝、復三卦，皆言「天行」以釋之。然則一陽生於坎，而六陽盛於巽，又豈穿鑿而為矛盾之論哉？學者謹馬可矣。象曰：風行水上，「渙」，先王以享於帝，立廟。</p><p>風者，「巽」也；水者，「坎」也。巽不取諸木而取諸風者，木浮於水，無以明「渙」之象。惟風行水上，而後渙之象可見矣。風行水上，水自動搖，風作於此，水散於彼，故先王以之享帝立廟。享帝以教欽，立廟以教愛，而民自化服矣。若風行地上，風至而後草偃，故先王以之省方觀民而設教焉。蓋相因而取象也。當天下渙然無難之時，享帝立廟，適其宜矣。雜卦曰：「渙，離也。」</p><p>渙之為卦，以風行水散而成。其在六爻，以血氣渙離為義。風者，氣也。水者，血也。血氣所以榮衛其身也。循於經絡，行於腑臟，晝夜不息，與天共地，相為流通，然後身安而無疾。若有所壅隔而不離，則疾之所由生也。是故渙與鹹艮，皆以爻位分配人之一身。然鹹艮之義，取喻人之形體。形體分佈於外，故其象顯，其辭明。渙之義，取喻人之氣血。氣血周流於內，故其象隱，其辭晦。然學者不可不深求其指歸也。氣屬乎陽，血屬乎陰，陽氣行則血氣俱行，陽氣滯則血氣俱滯。是故「渙」之諸爻，以陽居柔者，是血氣之所行也；以陰居剛者，是血氣之所滯也；以陽居剛、以陰居柔者，是血氣之所歸藏也。全「渙」之體，有身之象焉。中四爻以二陽包二陰，身腹之象也。奇畫在上，偶畫在下，首足之象也。初六言「拯」，九二言「奔」，六三言「躬」，六四言「群」，九五言「汗」，上九言「血」，各隨其所在而別之矣。初六：用拯馬壯，吉。象曰：「初六」之「吉」，順也。</p><p>初六，坎也，以陰居剛，而在下卦之下，上無其應，而承於九二之震，故曰：「用拯馬壯，吉。」「拯」，救拔也。「坎」為陷，震為動，故有「用拯」之象。「坎」為馬，為曳，震為馬，為作足，故有「馬壯」之象。初六以陰在下，宜取象於足，謂其體坎而承震，震為足，是以系之用拯也。拯於險難之中，而得馬壯，然後可以奔其機矣。故初六在「鹹」言「拇」，在「艮」言「趾」，而「渙」但言「用拯」，不以形體言之也。「拇」，取其動也；「趾」，取其止也。「渙」之初六，始乎止而卒乎動，故但言「用拯」，而拇趾之象著矣。鹹「艮」在下，有二陰，故初言「鹹趾」，二言「腓」。「渙」惟一陰，故但言「用拯」，而「腓」之象亦兼矣。自二至上爻皆言「渙」，而初獨不言者，謂其方拯而未離於難也。故子曰：「初六之吉，順也。」當「渙」之初，柔順而居下，故能自出於險陷之中，又得馬壯以行之，斯為吉矣。「明夷」六二以「坎」承「震」，其辭曰：「用拯馬壯，吉。」而子曰：「六二之吉，順以則也。」與此象同。九二，渙奔其機，悔亡。象曰：「渙奔其機」，得願也。</p><p>九二，震也。以陽居柔，而在下卦之中，上無其應，而介於二陰之間。二爻皆坎，而三又艮也，故曰「渙奔其機」。震為動，坎為險，故有奔其機之象。夫奔者以足，渙之足在下，而二言奔，何也？曰：初六之足弱而陷，九二之馬壯而動，故初言拯而二言奔，相因而成義矣。然則九二之所以能奔者，其惟陽氣之所在乎？「機」，舊讀為「幾」，人之所憑以為安者也。愚謂不然。夫人出於險陷之中，而履以平夷之地，斯以為安矣，而何至於憑几然後為安乎？若憑几然後為安，非痿則痺矣。按經典「幾」字無從「木」者。說文曰：「機，木名。」愚謂「機」當作「機」。機，不安也。書曰：「邦之機隉。」機與祪同。奔其機者，奔去其不安之地也，故曰「悔亡」。夫吉凶悔吝生乎動，九二動於險陷之中，能無悔乎？謂其去臲□而適乎易之塗，斯為「悔亡」矣。故子曰：「渙奔其機，得願也。」夫離險而就易，去危而即安，豈非人情之願也哉？彖之所謂「剛來而不窮」者也。</p><p>六三：渙其躬，無悔。象曰：「渙其躬」，志在外也。</p><p>六三上體為「艮」，下體為「坎」，以陰居剛，而在下卦之上，應乎上九之「兌」，故曰「渙其躬」。「躬」者，身也。「渙」者，「離」也。「坎」為陷，「艮」為止，「兌」為毀折，故有「渙其躬」之象。夫所取於「渙」者，謂其血氣周流於身，而無所壅滯也。居下體之上，在一卦之中，是血氣之海也，而「渙」之何哉？有所止者，有所陷，有所毀折，是將離去其身矣。筋攣而不隨，肌痺而不仁，氣脫而不收，血亡而不復，皆「渙其身」者也，故曰「無悔」。「離」，共身矣，雖復悔之，其能有救哉？故子曰：「渙其躬，志在外也。」夫一身之政聽命於心，一家之政聽命於長，一國之政聽命於君，天下之政聽命於王。是故血氣渙而不離於身，臣命渙而不離於國者，其志在內而無外交者也。當「渙」之時，上有九五為「渙」之主，而六三之志獨應於上，「艮」「兌」相與，有陷上毀折之象焉，是將志於外而離其君者也。離其君者，離其國也；離其國者，離其身也。系之「無悔」，宜哉！</p><p>六四：渙其群，元吉。渙有丘，匪夷所思。象曰：「渙其群，元吉」，光大也。</p><p>六四上體為巽，下體為艮，以陰居柔而在上卦之下，下無其應，而承於九五之震，故曰「渙其群」。群，類也。四之於三，其畫皆柔，其體皆「艮」，其類群矣。然三以艮而應於「兌」，四以「巽」而合於「震」，是以謂之「渙其群」也。「渙其群」者，猶「坤」之「喪朋」，大有之「匪其彭」也，故曰「元吉」。臣無有淫朋，人無有比德，斯之謂「元吉」矣。彖之所謂「柔得位乎外而上同」者也。近取諸身，其五臟六腑之謂與？五臟六腑各司其局，氣血周流，無所砥滯，是以系之「元吉」也。故曰「溪有邱」。渙，散也。邱，聚也。夫「渙」也者，必有其聚者也。無聚而「渙」，則其涸可立而侍也。陽為氣，陰為血。六四者血之所聚，而九五者，氣之所藏也。氣有所往，而血從之，四之所以上同也。故曰「匪夷所思」。思者，心也。夷者，類也。心之官則思，而非醜夷之思也。「渙其群」、「匪其夷」者，以所聽於心者也。是故六三為躬，六四為群。躬有四肢，群有腑臟。四肢之譬，則公侯伯子男也。腑臟之譬，則卿士大夫也。公侯伯子男不可以離於國，離於國則叛也。卿士大夫不可以不散其朋，不散其朋則黨也。此三、四之所以異也。傳有之曰：「文王觀於國，則列士壞植散群，長官者不成德。」則六四「渙其群」之謂也。至於庾斛不敢入於四境，諸侯無二心，則非所謂「渙其躬」矣。故子曰：「渙其群，元吉，光大也。」光大之辭，為九五言之也。五「渙其汗」，四「渙其群」，五之所以光大也。「鹹」以九四為心，故其辭曰「朋從爾思」，而子曰「未光大也」，明四非中正之謂也。「渙」以九五為心，其辭曰「匪夷所思」，而夫子則系之以「光大之辭」，明五得中正之位也。「渙」之時義若此，說者但以為離險釋難之卦，則是以「渙」為解者也。知其一而昧其二，得於初而失於終也。其或以為流離蕩析之卦，則是以「渙」為剝者也。是謂指東為西，指白為黑也。又或兼二說而兩取之，則是薰蕕不辨而並稱，冰炭無分而同謂也。嗚呼！惜哉！</p><p>九五：渙汗其大號。渙，王居，無咎。象曰：「王居無咎」，正位也。</p><p>九五，震也。以陽居剛，而在上卦之中，下無其應，而乘乎六四之「巽」，故曰：「渙汗其大號。」震為動，為雷；巽為入，為風，故有「渙號」之象。夫九五者，王之所居，而廟之所在也。宅中圖大，號令之所自出也。近取諸身，其神明之舍乎？心之液為汗，而王之命為號，是以取諸「渙汗」而謂之火號也。五臟之液，惟汗為能宣通，則以其出於心而周浹而四體故也。「渙其汗」，則血氣流通而身安；「汗其號」，則政教流通而天下治矣。漢劉向有言：「渙汗其大號，汗出而不反者也。」其在書曰：「令出惟行。」不惟汲取諸渙汗，不亦可乎？故曰：「渙，王居，無咎。」以九居五，其位在中，故有王居之象。當渙之時，萬物皆「渙」，而王獨居中，不應渙義，疑若有咎矣。然天下既渙，貴乎利貞以居之。王正在位而渙其號，是以居中而無咎。故子曰：「王居無咎，正位也。」二爻重言「渙」者，皆謂「渙」是散離之義，而六四以陰居柔，九五以陽居剛，又有震巽之合焉，故四言「有邱」，而五言「王居」，疑若不應時義，是以申其文以發其旨也。自二至五，有身腹之象，二為震，五亦為震，明陽氣之動，上下流動，故血氣之行無所偏滯也。或曰：陽為氣，陰為血，子以二五明陽氣之動，而血氣同稱，何也？曰：陽氣行則血與氣俱行，陽氣滯則血與氣俱滯，豈得獨言氣而不言血乎？猶之為國，有教有刑，刑主乎義，教主乎仁，而其行之與否，均系乎德之存亡也，豈可謂唐虞三代有教而無刑乎？</p><p>上九，渙其血，去逖出，旡咎。象曰：「渙其血」，遠害也。</p><p>上九，兌也。以陽居柔而在上卦之上，應乎六三之艮，而乘乎九五之震，故曰「渙其血去逖出」。三有坎體，坎為血，為憂傷。艮為止。震為動，為決。兌為說，為毀折，故有「血去逖出」之象。「逖」當作「愓」，與小畜六四之辭同。今本多作「逖」，非也。上九於身，為耳目鼻口之所在也。耳目鼻口，腑臟之外候，陽氣之會，精華之所發也。然下與六三有艮兌相與之情，陷而止焉，是身之病也。其榮衛否隔而不通，則其精華消耗，動於外候，耳目將為之聾盲，鼻口將為之瘖寒，聚而為癰疽，結而為痼癭，皆血氣之壅滯也。是必渙散其血，血去而愓出，斯為「旡咎」矣。夫血者，所以榮於內，而不可渙於外者也。惟瘀敗之血為害於身，則不可不渙耳。坎為憂傷，為心病，則敗血也，可不渙乎？故曰「旡咎」。而子曰：「渙其血，遠害也。」說者以「遠害」之文，訛「惕」為「逖」，則失之矣。上之所以能渙其血者，陽氣存焉故爾。血遇寒則止，得熱則行，是以至於上九而後渙也。渙其血者，湯艾鐵石之功也。遠其害，則刑罰徵誅之力也。刑罰徵誅，有國者之所不得已也。或曰：子不以正爻為宗廟，則上九之位，誰當居之？曰：初、上者，始終之義也。其初難知，其上易知，本末也。其在六三，則「渙其躬」；其在上九，則「渙其血」者，九五已正其位故也。夫子於「乾」之上九曰「貴而無位」。夫豈以人鬼相雜而後成卦乎？苟如延壽之論，則宗廟之爻而有「血去」「惕出」之文，是何義也？施於「王假有廟」之卦，已不能通，況其餘乎？序卦曰：渙者，離也。物不可以終離，故受之以</p><p>節。</p><p>節，「渙」之反也。自「渙」之「節」，坎反居上，「巽」反為「兌」，二五不動而成也。坎為水，「巽」為風，風行水上，則水動而散，是以謂之「渙」也。水行澤上，則澤得其節，是以謂之「節」也。說者皆以澤能止水，故謂之「節」。愚謂不然。夫「兌」之未重也，固以為止水之象矣。若「節」之成卦，但取止水為義，則理窮於「兌」，不得復有節象矣。而況以「坎」重兌，安得以一澤盡其義乎？且澤既止水矣，澤上安得有水乎？「困」之成卦，上兌下坎，宜曰「澤中有水」，而其象曰「澤無水」者，為其既重矣，嫌於無別也。況澤上水，安得但取止水為義乎？故「兌」之為「渙」也，澤決為川，而風木行於其上也。「渙」之為節也，水歸於澤，而為之水道，以節其盈虛也。此澤上之所以有水，「坎」、「兌」之所以為節，而節之所以次「渙」也。</p><p>節：亨，苦節不可貞。彖曰：「節，亨」，剛柔分而剛得中。若「節不可貞」，其道窮也。說以行險，當位以節，中正以通。天地節而四時成，節以制度，不傷財，不害民。</p><p>下兌上坎，成卦曰「節」者，初為兌，二為震，三為艮，四為坎。兌，澤也；坎，水也。澤也者，水之聚也。澤之上而為水焉，是泛溢之象也，而謂之節，何哉？為其有震、艮之象焉。震為木，艮為土，澤水之際而施土木焉，是隄防之象也。震為決，艮為止，澤上有水，時決而出，時閉而止，是溝洫之象也。設為隄防，導為溝洫，則水得其節，是以謂之節也。「節，亨，苦節不可貞」，何謂也？曰：水無節則泛，政無節則蕩。節以隄防，則水循其理；節以制度，則政得其宜。故曰：「節，亨。」節之所以亨者，剛柔分而剛得中也。在卦六爻，奇耦各居其半，剛柔分也。陽居二五，剛得中也。夫所以為節者，以剛柔寬猛不得其平矣。太剛則臲，太柔則壞，寬則民慢，猛則民殘。是故剛柔分而不偏，剛得中而不過，所以能節而通也。或曰：剛雖得中，而柔不得中，可以為節乎？曰：節之成卦，取諸水也，剛而動者也。水由地中行，則無氾濫懷襄之患，是之謂「剛得中」矣。剛得中則節道成矣，豈柔之問哉？故曰：「苦節不可貞。」貞者，正也，以此為政者也。節之得中，則受節者樂而甘；節之過甚，則受節者艱而苦。節而至於苦，物情所不能堪，豈可常也哉？故子曰：「節，亨，剛柔分而剛得中。苦節不可貞，其道窮也。」夫子既釋彖辭，又從而申之曰：「說以行險，當位以節，中正以通。天地節而四時成。節以制度，不傷財，不害民。」夫險者，人之所畏也，惟說以行之，則民從之矣。下兌上坎，所謂「說以行險」者與？「當位而節」，謂六四也。「中正以通」，謂九五也。苟能當位以節，中正以通，又何苦之有哉？天地之節，寒暑是也。寒極則暑，暑極則寒，四時之所以成也。節以制度，財用是也。國奢則示之以儉，國儉則示之禮，財之所以不傷，而民之所以不害也。國之政刑，無非節者，而獨言「財用」，蓋用之不節，有國者之通患也。</p><p>象曰：澤上有水，「節」，君子以制數度，議德行。澤者，「兌」也。「水」者，「坎」也。水之瀳至，其流有常，故君子以之常德行，習教事。澤上有水，其出有節，故君子以之「制數度，議德行」。虛則納之，滿則洩之，止而不窮，流而不盈，水之節也。直而溫，柔而立，恭而不勞，謹而不蕙，德之節也。寬以濟猛，猛以濟寬，禮中通而不離，樂和正而不流，政之節也。至於律度、量衡、宮室、車輿、衣裳、冕弁、冠婚、喪祭，莫不有數有度，皆節之道也。程氏曰：「凡德之大小、輕重、高下、文質，皆有數度。存諸中為德，發諸外為行。議以求中節也。」耿氏曰：「伯夷之清，柳下惠之和，則亦不中其節，在所議矣。」雜卦曰：節，止也。</p><p>節之為卦，以澤上有水而成。其在六爻，以水得其止為義。夫水之在宅，以滋養灌溉為功者也。有所止則為功，無所止則為害。設為隄防，導為溝洫，視其潦旱而出納之，察其盈虛而增損之。斂而不至於溢，散而不至於窮，所以為節止之道也。陽為剛，陰為柔；陽為動，陰為靜。陽為實，陰為虛。陽為氣，陰為形。故井以三陽為泉，三陰為井。節以三陽為水，三陰為防。水也，泉也，剛而動，氣而實者也。井也，防也，柔而靜，形而虛者也。水土之德，蓋如是矣。夫所以為節，節其過與不及，使之適中而止也。九五有「甘節」之吉，六四有「安節」之亨，所謂當位以節，而中正以通者也。初九在下，故「不出」而「旡咎」；上六已極，故「道窮」而真「兇」。所謂「苦節不可真」者也。若夫九五之水，亂於六三之防。亂於水，則水壅而防潰故也。九二之「兇」，六三之「嗟」，斯其義矣。</p><p>初九：不出戶庭，旡咎。象曰：「不出戶庭」，知通塞也。</p><p>初九，兌也。以陽居剛，而在下卦之下，應乎六四。四，坎艮也，故曰「不出戶庭」。說文曰：「戶，護也。半門為戶。」按古人門戶通稱，然對敵而言，則門為大而戶為小，門為外而戶為內矣。戶庭，內庭也。「兌」為門戶，其應在艮。艮，止也。上山下澤，無感應相與之情，而有懲忿窒欲之象，是以知其不出也。兌為口舌，故以言語為義。子曰：「古者言之不出。」又曰：「以約失之者鮮矣。」故曰「旡咎」。禮：「外言不入於梱，內言不出於梱。」戶庭之言，梱內之言也。謹而不出，夫何咎之有哉？故子曰：「不出戶庭，知通塞也。」澤居最下，宜塞而未宜通；及其既盈，宜通而不宜塞也。系曰：「亂之所生也，則言語以為階。君不密則失臣，臣不密則失身，機事不密則害成。」是以君子謹密而不出也，其當塞之時乎？</p><p>九二：不出門庭，兇。象曰：「不出門庭，兇」，失時極也。九二，「震」也。以陽居柔而在下卦之中，旡其應而承於六三。三，「艮」也，「巽」也，故曰「不出門庭」。震為出，為門庭。巽為入，艮為止，故亦有「不出門庭」之象。門庭，外庭也。謀之於內庭，則不出於旡咎矣；宜之於外庭而不出焉，是今不行於近也，而況於四方萬里之遠乎？故曰「兇」。人君之德澤號令不能出於門庭，則或害之矣，欲無兇，得乎？故子曰：「不出門庭，兇，失時極也。」九二之水已震乎澤中，又從而止焉，失其時極矣。或曰：說卦「艮為門闕」，而子言「兌為門戶，震為門庭」，何也？曰：兌上一陰，在人為口舌，在宮室為門戶矣。震之二陰，門之象也。艮上一陽有觀關之象，於闔闢何取哉？故兌為口舌，而震為善鳴，兌為戶庭，而震為門庭，相因而成象也。明夷之三亦體震，而四有坎離之象，故其辭曰：「出門庭而相見乎離」也。節之二三，有震巽之合，而遇艮止焉，是以系之「不出門庭」也。六三之艮為門闕，九二之震為門庭，初九之兌為門庭矣。震為闢戶，兌為闔戶，宜闔而止，是以旡咎；宜闢而止，是以「兇」也。豈不然哉？</p><p>六三：不節若，則嗟若，旡咎。象曰：「不節」之「嗟」，又誰咎也。</p><p>六三上體為艮，下體為巽，以陰居剛而在下卦之上，上旡其應，而乘於九二之震，故曰：「不節若則嗟」。艮為土，為止，巽為入，震為動，故有「不節」之象焉。節者，隄防之謂也。陽為水，陰為防。防者，所以制水也。故防在水上，水不至焉；水在防下，防不入焉。今九二以陽居柔，六三以陰居剛，是陽與水相混者也。水出於防而入於水也。傳曰：「水壅則潰，傷人必多。」九二之水動乎下，六三之防止於上，而不知所以宣導之，至於潰裂，故蕩而不可節，貞者何嗟及矣，故曰「旡咎」。子曰：「不節之嗟，又誰咎也？」</p><p>六四：安節，亨。象曰：「安節」之「亨」，承上道也。</p><p>六四上體為坎，下體為艮，以陰居柔而在上卦之下，應於初九之兌，而承於九五之震，故曰「安節」。坎為水，為陷；艮為山，為止。止者，隄防之象也；陷者，溝洫之象也。設為隄防而導其溝洫，水者所以安行而受其節也。兌為說，震為行，坎為險。說以行險，是以知其「安節」矣，故曰「亨」。子曰：「安節」之亨，承上道也。上謂九五，九五水也。水在澤上，則六四者豈非承水之道乎？居近君之位，得承上之道，順物之性，安而節之，此其所以「亨」也。</p><p>九五：甘節，吉，往有尚。象曰：「甘節」之吉，居位中也。</p><p>九五，「震」也。以陽居剛而在上卦之中，下旡其應，而介於二陰之間，二爻皆「坎」，而四又「艮」也，故曰「甘節」。「甘」，中央之味也。書曰「稼穡作甘」是也。「坎」為水，「艮」為土，「震」為耕稼，而五得中行，故有「甘節」之象。夫節以制度，人情之所不樂也。節而至於甘，則節之功見矣，故曰「吉」。又曰「往有尚」。「往有尚」者，「坎」之所以為功也。夫所以設為隄防，導為溝洫，以時而出納之者，所以為水旱之備也歟！上六有炎上之苦，而九五以甘濟之，是謂「往」而「有尚」也。體乎中正，行於險中，以成稼穡之功，斯為吉矣。故子曰：「甘節之吉。」「居位中」雲者，水由地中行也。六四為承上道，九五為居位中，則澤上有水，其義粲然矣。</p><p>上六：苦節，貞兇，悔亡。象曰：「苦節，貞兇」，其道窮也。</p><p>上六，「坎」也。以陰居柔而在上卦之上，下無其應，而乘於九五之震，故曰「苦節」。「苦」，炎上之味也。「坎」之窮為「離」，六四既為「坎」矣，上六居卦之窮，是以有炎上之味也。潤澤之所不及，而「離」日暵之，故其味焦而苦也。節而至於苦，物情所以不堪，故曰「貞兇」。以此為正，則兇矣。然而乂系之以「悔亡」，何謂也？上六，節之窮也，窮則變矣。節而至於苦，貞之則兇，變之則悔亡。下無其應，而乘於九五，五以中正與之為配，剛柔相資，甘苦相濟，虛實相輔，故其悔至於亡也。陽為德，陰為刑。水譬則法禁也。以法禁裁惠澤，猶以數度議德行也。慶賞施惠，人之所欲，故謂之甘；刑威法禁，人之所畏，故謂之苦。以甘濟苦，和羹之謂也。「悔亡」，不亦宜乎？說者或謂節有戒飲食之義，世人嗜甘而不嗜苦，故甘節為吉，而苦節為兇。愚謂節甘如前說可矣，節苦者何遽至於兇乎？夫節之為義，節其出也，非節其入也。此說似是而非，故辨而正之。子曰：「苦節貞兇，其道窮也。」九二在中而非中，上六居正而非正，然後君子知大中至正之所在矣。周易經傳集解卷三十，</p>',35)])])}const m=a(s,[["render",n]]);export{h as __pageData,m as default};
